# Generated by build.py from recipe.yml for recipe ldap-bind-with-ntlm. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/.surl/ldap' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/.surl/ldap/directory.ldif'), "dn: dc=example,dc=com`nobjectClass: domain`ndc: example`n`ndn: cn=alice,dc=example,dc=com`nobjectClass: person`ncn: alice`nmail: alice@example.com`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--auth', 'ntlm', '-u', 'alice:s3cret', 'ldap://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --ntlm -u alice:s3cret "ldap://127.0.0.1:8080/dc=example,dc=com?mail?sub?(cn=alice)" } finally { Stop-Process $server0 }
